// Generate daily digest content with proper data handling
const jobs = $input.all()[0].json || [];
const stats = $input.all()[1].json || [];

// Get user ID from environment or workflow settings
const userId = process.env.USER_ID || $workflow.settings?.userId;
if (!userId) {
  console.warn('USER_ID not found - using default');
}

// Calculate summary metrics
const totalJobs = jobs.length;
const highScoreJobs = jobs.filter(job => (job.ai_match_score || 0) >= 8);
const mediumScoreJobs = jobs.filter(job => (job.ai_match_score || 0) >= 7 && (job.ai_match_score || 0) < 8);
const avgScore = totalJobs > 0 ? (jobs.reduce((sum, job) => sum + (job.ai_match_score || 0), 0) / totalJobs).toFixed(1) : 0;

// Top sources
const sourceStats = {};
jobs.forEach(job => {
  const source = job.source || 'Unknown';
  sourceStats[source] = (sourceStats[source] || 0) + 1;
});
const topSources = Object.entries(sourceStats)
  .sort(([,a], [,b]) => b - a)
  .slice(0, 3);

// Generate HTML email content (same as before, but cleaned up)
const generateJobCard = (job) => `
  <div style="border: 1px solid #e0e0e0; border-radius: 8px; padding: 16px; margin: 12px 0; background: ${(job.ai_match_score || 0) >= 8 ? '#f0f9ff' : '#ffffff'};">
    <div style="display: flex; justify-content: space-between; align-items: start; margin-bottom: 8px;">
      <h3 style="margin: 0; color: #1f2937; font-size: 18px;">${escapeHtml(job.role)}</h3>
      <span style="background: ${(job.ai_match_score || 0) >= 8 ? '#10b981' : (job.ai_match_score || 0) >= 7 ? '#f59e0b' : '#6b7280'}; color: white; padding: 4px 8px; border-radius: 12px; font-size: 12px; font-weight: bold;">
        ${job.ai_match_score || 'N/A'}/10
      </span>
    </div>
    <p style="margin: 4px 0; color: #4b5563; font-weight: 500;">${escapeHtml(job.company)} • ${escapeHtml(job.location || 'Location TBD')}</p>
    <p style="margin: 8px 0; color: #6b7280; font-size: 14px;">${escapeHtml((job.description || '').substring(0, 200))}${job.description && job.description.length > 200 ? '...' : ''}</p>
    <div style="margin-top: 12px;">
      <a href="${job.url}" style="background: #2563eb; color: white; padding: 8px 16px; text-decoration: none; border-radius: 6px; font-size: 14px; margin-right: 8px;">View Job</a>
      <span style="color: #6b7280; font-size: 12px;">Source: ${escapeHtml(job.source || 'Unknown')}</span>
    </div>
  </div>
`;

// HTML escape function
function escapeHtml(text) {
  if (!text) return '';
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const emailHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Daily Job Digest</title>
</head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.6; color: #333; max-width: 800px; margin: 0 auto; padding: 20px;">

  <div style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 30px; border-radius: 12px; margin-bottom: 30px; text-align: center;">
    <h1 style="margin: 0; font-size: 28px;">📊 Daily Job Digest</h1>
    <p style="margin: 8px 0 0 0; opacity: 0.9;">${new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
  </div>

  <div style="background: #f8fafc; border-radius: 12px; padding: 24px; margin-bottom: 30px;">
    <h2 style="margin: 0 0 20px 0; color: #1f2937;">📈 Today's Summary</h2>
    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 16px;">
      <div style="text-align: center; padding: 16px; background: white; border-radius: 8px;">
        <div style="font-size: 32px; font-weight: bold; color: #2563eb;">${totalJobs}</div>
        <div style="color: #6b7280; font-size: 14px;">Jobs Found</div>
      </div>
      <div style="text-align: center; padding: 16px; background: white; border-radius: 8px;">
        <div style="font-size: 32px; font-weight: bold; color: #10b981;">${highScoreJobs.length}</div>
        <div style="color: #6b7280; font-size: 14px;">High Score (8+)</div>
      </div>
      <div style="text-align: center; padding: 16px; background: white; border-radius: 8px;">
        <div style="font-size: 32px; font-weight: bold; color: #f59e0b;">${mediumScoreJobs.length}</div>
        <div style="color: #6b7280; font-size: 14px;">Good Score (7+)</div>
      </div>
      <div style="text-align: center; padding: 16px; background: white; border-radius: 8px;">
        <div style="font-size: 32px; font-weight: bold; color: #8b5cf6;">${avgScore}</div>
        <div style="color: #6b7280; font-size: 14px;">Avg Score</div>
      </div>
    </div>
  </div>

  ${highScoreJobs.length > 0 ? `
  <div style="margin-bottom: 30px;">
    <h2 style="color: #1f2937; border-bottom: 2px solid #10b981; padding-bottom: 8px;">⭐ High Priority Jobs (Score 8+)</h2>
    ${highScoreJobs.slice(0, 5).map(generateJobCard).join('')}
  </div>
  ` : ''}

  ${mediumScoreJobs.length > 0 ? `
  <div style="margin-bottom: 30px;">
    <h2 style="color: #1f2937; border-bottom: 2px solid #f59e0b; padding-bottom: 8px;">📋 Worth Reviewing (Score 7+)</h2>
    ${mediumScoreJobs.slice(0, 3).map(generateJobCard).join('')}
  </div>
  ` : ''}

  ${topSources.length > 0 ? `
  <div style="background: #f8fafc; border-radius: 12px; padding: 24px; margin-bottom: 30px;">
    <h2 style="margin: 0 0 16px 0; color: #1f2937;">📍 Top Sources Today</h2>
    ${topSources.map(([source, count]) => `
      <div style="display: flex; justify-content: space-between; padding: 8px 0; border-bottom: 1px solid #e5e7eb;">
        <span>${escapeHtml(source)}</span>
        <span style="font-weight: bold; color: #2563eb;">${count} jobs</span>
      </div>
    `).join('')}
  </div>
  ` : ''}

  <div style="text-align: center; padding: 20px; color: #6b7280; border-top: 1px solid #e5e7eb;">
    <p style="margin: 0;">🤖 Generated by your job search automation</p>
    <p style="margin: 4px 0 0 0; font-size: 12px;">View your full dashboard at <a href="https://ekazee01-lgtm.github.io/jobsearch/tracker.html" style="color: #2563eb;">Job Tracker</a></p>
  </div>

</body>
</html>
`;

// Generate plain text version
const plainText = `
📊 DAILY JOB DIGEST - ${new Date().toLocaleDateString()}

📈 TODAY'S SUMMARY:
• Total Jobs Found: ${totalJobs}
• High Score Jobs (8+): ${highScoreJobs.length}
• Good Score Jobs (7+): ${mediumScoreJobs.length}
• Average Score: ${avgScore}/10

⭐ HIGH PRIORITY JOBS (Score 8+):
${highScoreJobs.slice(0, 5).map(job => `• ${job.role} at ${job.company} - Score: ${job.ai_match_score}/10\n  ${job.url}`).join('\n\n')}

📋 WORTH REVIEWING (Score 7+):
${mediumScoreJobs.slice(0, 3).map(job => `• ${job.role} at ${job.company} - Score: ${job.ai_match_score}/10\n  ${job.url}`).join('\n\n')}

📍 TOP SOURCES TODAY:
${topSources.map(([source, count]) => `• ${source}: ${count} jobs`).join('\n')}

---
🤖 Generated by your job search automation
View full dashboard: https://ekazee01-lgtm.github.io/jobsearch/tracker.html
`;

// Determine if we should send (only for 7+ scored jobs or if explicitly requested)
const qualityJobs = highScoreJobs.length + mediumScoreJobs.length;
const shouldSend = totalJobs > 0 && (qualityJobs > 0 || totalJobs >= 10); // Send if we have quality jobs OR many jobs

return {
  json: {
    htmlContent: emailHtml,
    plainContent: plainText,
    stats: {
      totalJobs,
      highScoreJobs: highScoreJobs.length,
      mediumScoreJobs: mediumScoreJobs.length,
      avgScore: parseFloat(avgScore),
      qualityJobs
    },
    shouldSend,
    userId: userId || null
  }
};
